"""Fill text to a line width, keeping paragraphs apart."""
import re


def wrap(text, width):
    """Greedily fill each paragraph to at most width characters.

    Paragraphs are separated by blank lines; within a paragraph all whitespace collapses to
    single spaces. A word longer than width goes on its own line, unbroken. Paragraphs are
    joined by exactly one empty line. Returns the lines joined with "\\n", no trailing newline.
    """
    if width < 1:
        raise ValueError(f"width must be at least 1, not {width}")
    lines = []
    for block in re.split(r"\n\s*\n", text):
        words = block.split()
        if not words:
            continue
        if lines:
            lines.append("")
        lines.extend(_fill(words, width))
    return "\n".join(lines)


def _fill(words, width):
    lines, cur = [], ""
    for word in words:
        if cur and len(cur) + 1 + len(word) <= width:
            cur += " " + word
            continue
        if cur:
            lines.append(cur)
        cur = word
    if cur:
        lines.append(cur)
    return lines

