        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")
        self.assertEqual(wrap("aaa bbb ccc", 11), "aaa bbb ccc")

    def test_exact_width_fits(self):
        self.assertEqual(wrap("ab cd", 5), "ab cd")

    def test_whitespace_collapses_inside_paragraph(self):
        self.assertEqual(wrap("a   b\n\tc\nd", 20), "a b c d")

    def test_long_word_on_its_own_line(self):
        self.assertEqual(wrap("hi suprcalifragilistic ok", 5),
                         "hi\nsuprcalifragilistic\nok")

    def test_long_word_first(self):
        self.assertEqual(wrap("abcdefgh x", 3), "abcdefgh\nx")

    def test_hyphenated_word_not_split(self):
        self.assertEqual(wrap("well-known word", 6), "well-known\nword")

    def test_paragraphs_separated_by_one_empty_line(self):
        self.assertEqual(wrap("one two\n\n\nthree", 20), "one two\n\nthree")

    def test_blank_lines_with_whitespace_separate_paragraphs(self):
        self.assertEqual(wrap("one\n  \t \ntwo", 20), "one\n\ntwo")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap("\n\n  one two \n\n", 20), "one two")

    def test_empty_text(self):
        self.assertEqual(wrap("", 10), "")
        self.assertEqual(wrap(" \n \n", 10), "")

    def test_width_below_one_raises(self):
        with self.assertRaises(ValueError):
            wrap("abc", 0)
